  c.talk.pl = [{"c":"childhood","t":"Jaka gra była waszą ulubioną w dzieciństwie?"},{"c":"childhood","t":"Jakie danie z dzieciństwa chętnie zjecie nawet teraz?"},{"c":"childhood","t":"Jaki zawód był waszym marzeniem w dzieciństwie?"},{"c":"childhood","t":"Jaka bajka z dzieciństwa nigdy się nie nudziła?"},{"c":"childhood","t":"Jaka zabawka była waszym największym skarbem?"},{"c":"childhood","t":"Jakie jest wasze najpiękniejsze wspomnienie z wakacji?"},{"c":"childhood","t":"Czego nauczyli was dziadkowie?"},{"c":"childhood","t":"Który przedmiot w szkole przychodził wam najłatwiej?"},{"c":"childhood","t":"Czy w waszym dzieciństwie była jakaś sekretna kryjówka?"},{"c":"childhood","t":"Jaka książka czytana na głos była ulubiona w waszym dzieciństwie?"},{"c":"childhood","t":"Jakie było wasze pierwsze zwierzątko, a jeśli go nie było — o jakim było marzenie?"},{"c":"childhood","t":"W jakie zabawy grało się na podwórku z innymi dziećmi?"},{"c":"childhood","t":"Jaki zapach od razu przenosi was do dzieciństwa?"},{"c":"childhood","t":"Co było waszą kolekcją w dzieciństwie?"},{"c":"childhood","t":"Jaka najzabawniejsza historia wydarzyła się w waszej szkole?"},{"c":"childhood","t":"Na jaki dzień w roku najbardziej czekało się w dzieciństwie?"},{"c":"childhood","t":"Co najfajniej było budować albo robić własnymi rękami?"},{"c":"childhood","t":"Która domowa zasada wydawała się wam najdziwniejsza w dzieciństwie?"},{"c":"childhood","t":"Jakie słodycze kupowało się za kieszonkowe?"},{"c":"childhood","t":"Kto był pierwszym przyjacielem lub pierwszą przyjaciółką i jakie były wasze wspólne zabawy?"},{"c":"childhood","t":"Co w dzieciństwie budziło strach, a dziś śmieszy?"},{"c":"childhood","t":"Jakie zimowe zabawy na dworze były najlepsze w waszym dzieciństwie?"},{"c":"childhood","t":"Jakie historie z waszego dzieciństwa opowiada rodzina?"},{"c":"childhood","t":"Co wychodziło wam lepiej niż komukolwiek w klasie?"},{"c":"childhood","t":"Jak wyglądał wasz tornister albo piórnik?"},{"c":"childhood","t":"Jaki prezent z dzieciństwa najbardziej zapadł wam w pamięć?"},{"c":"travel","t":"Do jakiego kraju chętnie wyruszycie choćby jutro?"},{"c":"travel","t":"Które miejsce jest najpiękniejsze ze wszystkich, które znacie?"},{"c":"travel","t":"Góry czy morze — i dlaczego?"},{"c":"travel","t":"Jakie miasto chcecie zobaczyć nocą?"},{"c":"travel","t":"Co zawsze zabieracie w podróż?"},{"c":"travel","t":"Pociąg, samolot czy samochód — jak lubicie podróżować?"},{"c":"travel","t":"Jakie nietypowe jedzenie udało się wam spróbować w podróży?"},{"c":"travel","t":"Jaka pamiątka z podróży wciąż jest u was w domu?"},{"c":"travel","t":"Dokąd pojechać, mając tylko godzinę na spakowanie się?"},{"c":"travel","t":"Jakie miejsce w waszym mieście pokażecie gościowi jako pierwsze?"},{"c":"travel","t":"Jakiego języka chcecie się nauczyć do podróżowania?"},{"c":"travel","t":"Namiot w lesie czy hotel z widokiem — co wybieracie?"},{"c":"travel","t":"Jaka była najdłuższa podróż w waszym życiu?"},{"c":"travel","t":"Co chcecie zobaczyć: zorzę polarną, pustynię czy dżunglę?"},{"c":"travel","t":"W podróży wolicie plany czy niespodzianki?"},{"c":"travel","t":"Co wybieracie: lot balonem, kolejkę linową czy prom?"},{"c":"travel","t":"Jakie miejsce z książki albo filmu chcecie odwiedzić?"},{"c":"travel","t":"Jak spędzacie czas podczas długiej podróży?"},{"c":"travel","t":"Jakie miejsce chcecie zobaczyć z lotu ptaka?"},{"c":"travel","t":"Jaki kraj znacie z kuchni, choć jeszcze nie udało się tam pojechać?"},{"c":"travel","t":"Gdzie chcecie oglądać wschód słońca?"},{"c":"travel","t":"O czym zwykle zapominacie przy pakowaniu?"},{"c":"travel","t":"Jakie najmniejsze miasteczko przypadło wam do gustu?"},{"c":"travel","t":"Gdyby można było na miesiąc zamieszkać w dowolnym mieście — które wybieracie?"},{"c":"travel","t":"Jaką podróż chcecie powtórzyć?"},{"c":"travel","t":"Co jest ciekawsze: muzea czy spacery po ulicach?"},{"c":"food","t":"Jakie danie gotujecie najlepiej?"},{"c":"food","t":"Śniadanie na słodko czy na słono?"},{"c":"food","t":"Jakie jedzenie możecie jeść codziennie?"},{"c":"food","t":"Jaki jest wasz ulubiony owoc?"},{"c":"food","t":"Jakiego dania jeszcze nie znacie, a chcecie spróbować?"},{"c":"food","t":"Herbata czy kawa — i z czym?"},{"c":"food","t":"Jaki najdziwniejszy smak lodów udało się wam spróbować?"},{"c":"food","t":"Co ugotujecie dla gościa z innego kraju?"},{"c":"food","t":"Pizza, zupa czy sałatka: co wybieracie na obiad?"},{"c":"food","t":"Jaki przepis przechodzi w waszej rodzinie z pokolenia na pokolenie?"},{"c":"food","t":"Jakie jedzenie przypomina wam dom?"},{"c":"food","t":"Co lubicie dodawać prawie do wszystkiego?"},{"c":"food","t":"Co chcecie razem upiec?"},{"c":"food","t":"Ostre jedzenie: tak czy nie?"},{"c":"food","t":"Jaka przekąska jest najlepsza na podróż?"},{"c":"food","t":"Jakie danie kiedyś zupełnie się nie udało?"},{"c":"food","t":"Którą kuchnię świata lubicie najbardziej?"},{"c":"food","t":"Co smakuje lepiej: domowe jedzenie czy z kawiarni?"},{"c":"food","t":"Co pijecie, kiedy jest zimno?"},{"c":"food","t":"Jak wygląda wasze idealne śniadanie?"},{"c":"food","t":"Jakie jedzenie nie smakowało wam w dzieciństwie, a teraz smakuje?"},{"c":"food","t":"Gdyby powstała wasza kawiarnia, co byłoby w menu?"},{"c":"food","t":"Jaka zupa jest najsmaczniejsza na świecie?"},{"c":"food","t":"Ile łyżeczek cukru wsypujecie do herbaty?"},{"c":"food","t":"Jakiego dania chcecie nauczyć się gotować?"},{"c":"food","t":"Czekolada: gorzka, mleczna czy biała?"},{"c":"dreams","t":"Jakiej umiejętności chcecie się nauczyć w tym roku?"},{"c":"dreams","t":"Gdzie chcecie mieszkać za dziesięć lat?"},{"c":"dreams","t":"Jaki jest wasz największy plan na lato?"},{"c":"dreams","t":"Wymarzony dom: nad morzem, w lesie czy w mieście?"},{"c":"dreams","t":"W jakim języku marzycie mówić płynnie?"},{"c":"dreams","t":"Czego chcecie uczyć innych?"},{"c":"dreams","t":"Jaki dobry uczynek marzy się wam najbardziej?"},{"c":"dreams","t":"Co chcecie zrobić własnymi rękami?"},{"c":"dreams","t":"Jaki sport chcecie wypróbować?"},{"c":"dreams","t":"Jakie miejsce na mapie marzy się wam najbardziej?"},{"c":"dreams","t":"Gdyby był wolny rok, czym go wypełnić?"},{"c":"dreams","t":"Jaką roślinę albo jaki ogród chcecie wyhodować?"},{"c":"dreams","t":"Jaką książkę marzycie przeczytać albo napisać?"},{"c":"dreams","t":"Jaką umiejętność z dzieciństwa chcecie odzyskać?"},{"c":"dreams","t":"Jaki rekord chcecie pobić?"},{"c":"dreams","t":"Co chcecie zrobić przed końcem roku?"},{"c":"dreams","t":"Jak wygląda wasz idealny dzień wolny?"},{"c":"dreams","t":"Jaki zawód chcecie wypróbować choćby na jeden dzień?"},{"c":"dreams","t":"Jakie zwierzę chcecie kiedyś zobaczyć na żywo?"},{"c":"dreams","t":"Jaki mały krok w stronę marzenia możecie zrobić w tym tygodniu?"},{"c":"dreams","t":"Jaką podróż zaplanujecie razem?"},{"c":"dreams","t":"Czego chcecie nauczyć się od siebie nawzajem?"},{"c":"dreams","t":"Jaki projekt od dawna czeka na rozpoczęcie?"},{"c":"dreams","t":"Gdzie chcecie spędzić cały spokojny dzień?"},{"c":"dreams","t":"Jakie spotkanie zorganizujecie dla wszystkich przyjaciół?"},{"c":"dreams","t":"Co warto wynaleźć, żeby ułatwić życie?"},{"c":"whatif","t":"Gdyby można było latać, dokąd najpierw?"},{"c":"whatif","t":"Gdyby zwierzęta mówiły, z którym warto by pogadać?"},{"c":"whatif","t":"Jeden dzień niewidzialności — co wtedy robicie?"},{"c":"whatif","t":"Gdyby można było wybrać dowolny talent, który by to był?"},{"c":"whatif","t":"Gdyby można było zamieszkać w książce, która by to była?"},{"c":"whatif","t":"Gdyby był robot pomocnik, czym by się zajmował?"},{"c":"whatif","t":"Znajomość wszystkich języków — z kim wtedy porozmawiacie?"},{"c":"whatif","t":"Gdyby można było teraz przenieść się do dowolnej pory roku, która by to była?"},{"c":"whatif","t":"Gdyby była wasza własna wyspa, co by na niej było?"},{"c":"whatif","t":"Po zmniejszeniu się do rozmiaru mrówki — co warto by zbadać?"},{"c":"whatif","t":"Gdyby można było wymyślić nowy wyjątkowy dzień w roku, jak by wyglądał?"},{"c":"whatif","t":"Gdyby można było przewinąć dzień, jaką chwilę warto by powtórzyć?"},{"c":"whatif","t":"Gdyby wasz charakter był rodzajem pogody, jaki by to był?"},{"c":"whatif","t":"Gdyby można było żyć pod wodą, co warto by tam zbudować?"},{"c":"whatif","t":"Gdyby można było na jeden dzień zamienić się z kimś pracą, kto by to był?"},{"c":"whatif","t":"Gdyby było wasze własne muzeum, co by w nim było?"},{"c":"whatif","t":"Gdyby można było rozmawiać z roślinami, o co warto by je zapytać?"},{"c":"whatif","t":"Gdyby na jeden dzień zniknęły wszystkie samochody, dokąd wybrać się na spacer?"},{"c":"whatif","t":"Gdyby wasz charakter był smakiem lodów, jaki by to był smak?"},{"c":"whatif","t":"Gdyby można było przez jeden dzień żyć w innym kraju, jaki by to był kraj?"},{"c":"whatif","t":"Gdyby wasz dom miał koła, dokąd by pojechał?"},{"c":"whatif","t":"Gdyby powstał wasz własny sklep, co by w nim było na sprzedaż?"},{"c":"whatif","t":"Gdyby śnieg padał codziennie, co by się zmieniło?"},{"c":"whatif","t":"Gdyby była maszyna czasu na jedną godzinę, dokąd się wybrać?"},{"c":"whatif","t":"Gdyby można było nauczyć zwierzątko jednej sztuczki, jaka by to była?"},{"c":"whatif","t":"Gdyby powstała wasza książka, jaki miałaby tytuł?"},{"c":"funny","t":"Jaka była najzabawniejsza pomyłka autokorekty w waszych wiadomościach?"},{"c":"funny","t":"Jakie słowo długo sprawiało wam kłopot z wymową?"},{"c":"funny","t":"Jaki był najdziwniejszy sen w waszym życiu?"},{"c":"funny","t":"Co zawsze was rozśmiesza, nawet kiedy nie wypada?"},{"c":"funny","t":"Jaki był najgłupszy zakup w waszym życiu?"},{"c":"funny","t":"Które zwierzę wydaje się wam najzabawniejsze?"},{"c":"funny","t":"Opowiedzcie o sytuacji, w której nic nie poszło zgodnie z planem, a wyszło zabawnie."},{"c":"funny","t":"Jaki dowcip znacie na pamięć?"},{"c":"funny","t":"Jaki tytuł miałaby kreskówka o waszym życiu?"},{"c":"funny","t":"Jaki zabawny nawyk zauważacie u siebie?"},{"c":"funny","t":"Jakie najzabawniejsze przezwisko do was przylgnęło?"},{"c":"funny","t":"Gdyby kot albo pies prowadził bloga, o czym by pisał?"},{"c":"funny","t":"Przy jakim filmie śmiech doprowadził was do łez?"},{"c":"funny","t":"Jaka zabawna sytuacja przytrafiła się wam w komunikacji miejskiej?"},{"c":"funny","t":"Jakie najdziwniejsze połączenie smaków wam smakuje?"},{"c":"funny","t":"Jaki dźwięk najlepiej opisuje wasze poranki?"},{"c":"funny","t":"Czego szukacie czasem, trzymając to w ręce?"},{"c":"funny","t":"Jaką zabawną historię o pogodzie znacie?"},{"c":"funny","t":"Gdyby warzywa miały charakter, które byłoby największym zrzędą?"},{"c":"funny","t":"Jakie jest najzabawniejsze słowo w obcym języku, które znacie?"},{"c":"funny","t":"Co zdarza się wam robić, kiedy nikt nie patrzy?"},{"c":"funny","t":"Jakie zabawne powiedzonko często pada w waszym domu?"},{"c":"funny","t":"Jak opisałby was talerz po obiedzie?"},{"c":"funny","t":"Jakie jest wasze najbardziej niefortunne zdjęcie?"},{"c":"funny","t":"Jaką zupełnie bezużyteczną supermoc wybieracie?"},{"c":"funny","t":"Gdyby wasz poranek miał nagłówek w gazecie, jak by brzmiał?"}];
