  c.talk.el = [{"c":"childhood","t":"Με ποιο παιχνίδι παίζατε πιο ευχαρίστως στα παιδικά σας χρόνια;"},{"c":"childhood","t":"Ποιο φαγητό των παιδικών σας χρόνων θα τρώγατε με χαρά τώρα αμέσως;"},{"c":"childhood","t":"Ποιο επάγγελμα ονειρευόσασταν ως παιδιά;"},{"c":"childhood","t":"Ποιο κινούμενο σχέδιο θα βλέπατε ξανά και ξανά;"},{"c":"childhood","t":"Ποιο ήταν το πιο πολύτιμο παιχνίδι σας;"},{"c":"childhood","t":"Ποια είναι η πιο φωτεινή σας ανάμνηση από τις καλοκαιρινές διακοπές;"},{"c":"childhood","t":"Τι σας έμαθε ένας παππούς ή μια γιαγιά;"},{"c":"childhood","t":"Ποιο σχολικό μάθημα σας ερχόταν πιο εύκολα;"},{"c":"childhood","t":"Είχατε κάποια μυστική κρυψώνα ως παιδιά;"},{"c":"childhood","t":"Ποιο βιβλίο θέλατε να σας διαβάζουν δυνατά ως παιδιά;"},{"c":"childhood","t":"Ποιο ήταν το πρώτο σας κατοικίδιο ή ποιο κατοικίδιο θέλατε να έχετε;"},{"c":"childhood","t":"Τι παιχνίδια παίζατε έξω με άλλα παιδιά;"},{"c":"childhood","t":"Ποια μυρωδιά σας γυρίζει αμέσως στα παιδικά σας χρόνια;"},{"c":"childhood","t":"Τι μαζεύατε ως παιδιά;"},{"c":"childhood","t":"Ποιο ήταν το πιο αστείο περιστατικό στο σχολείο σας;"},{"c":"childhood","t":"Ποια μέρα του χρόνου περιμένατε πιο πολύ ως παιδιά;"},{"c":"childhood","t":"Τι σας άρεσε να φτιάχνετε με τα χέρια σας;"},{"c":"childhood","t":"Ποιος κανόνας του σπιτιού σας φαινόταν πιο παράξενος ως παιδιά;"},{"c":"childhood","t":"Ποια λιχουδιά αγοράζατε με το χαρτζιλίκι σας;"},{"c":"childhood","t":"Ποια ήταν η πρώτη σας φιλία και τι κάνατε μαζί;"},{"c":"childhood","t":"Τι σας φόβιζε στα παιδικά σας χρόνια που τώρα σας φαίνεται αστείο;"},{"c":"childhood","t":"Τι σας άρεσε να κάνετε έξω τον χειμώνα ως παιδιά;"},{"c":"childhood","t":"Ποιες ιστορίες λέει η οικογένειά σας για τα παιδικά σας χρόνια;"},{"c":"childhood","t":"Τι μπορούσατε να κάνετε καλύτερα από όλους στην τάξη σας;"},{"c":"childhood","t":"Πώς ήταν η σχολική σας τσάντα ή η κασετίνα σας;"},{"c":"childhood","t":"Ποιο δώρο από τα παιδικά σας χρόνια θυμάστε περισσότερο;"},{"c":"travel","t":"Για ποια χώρα θα ξεκινούσατε αύριο κιόλας;"},{"c":"travel","t":"Ποιο είναι το πιο όμορφο μέρος που έχετε επισκεφθεί;"},{"c":"travel","t":"Βουνό ή θάλασσα — και γιατί;"},{"c":"travel","t":"Ποια πόλη θα θέλατε να δείτε τη νύχτα;"},{"c":"travel","t":"Τι παίρνετε πάντα μαζί σας σε ένα ταξίδι;"},{"c":"travel","t":"Τρένο, αεροπλάνο ή αυτοκίνητο — πώς προτιμάτε να ταξιδεύετε;"},{"c":"travel","t":"Ποιο ασυνήθιστο φαγητό έχετε δοκιμάσει σε ταξίδι;"},{"c":"travel","t":"Ποιο σουβενίρ από κάποιο ταξίδι κρατάτε ακόμα;"},{"c":"travel","t":"Πού θα πηγαίνατε αν είχατε μόνο μία ώρα για να ετοιμάσετε βαλίτσα;"},{"c":"travel","t":"Ποιο μέρος της πόλης σας θα δείχνατε πρώτο σε έναν επισκέπτη;"},{"c":"travel","t":"Ποια γλώσσα θα θέλατε να μάθετε για τα ταξίδια;"},{"c":"travel","t":"Σκηνή στο δάσος ή ξενοδοχείο με θέα — τι θα διαλέγατε;"},{"c":"travel","t":"Ποιο είναι το μεγαλύτερο ταξίδι που έχετε κάνει;"},{"c":"travel","t":"Τι θα θέλατε να δείτε: το βόρειο σέλας, μια έρημο ή μια ζούγκλα;"},{"c":"travel","t":"Στα ταξίδια προτιμάτε σχέδια ή εκπλήξεις;"},{"c":"travel","t":"Τι θα δοκιμάζατε: αερόστατο, τελεφερίκ ή φέρι;"},{"c":"travel","t":"Ποιο μέρος από βιβλίο ή ταινία θα θέλατε να επισκεφθείτε;"},{"c":"travel","t":"Τι κάνετε για να περάσει η ώρα σε ένα μεγάλο ταξίδι;"},{"c":"travel","t":"Ποιο μέρος θα θέλατε να δείτε από ψηλά;"},{"c":"travel","t":"Ποια χώρα γνωρίζετε από την κουζίνα της αλλά δεν την έχετε επισκεφθεί ποτέ;"},{"c":"travel","t":"Πού θα θέλατε να δείτε την ανατολή του ήλιου;"},{"c":"travel","t":"Τι ξεχνάτε συνήθως να βάλετε στη βαλίτσα;"},{"c":"travel","t":"Ποια είναι η πιο μικρή πόλη που σας άρεσε;"},{"c":"travel","t":"Αν μπορούσατε να ζήσετε έναν μήνα σε οποιαδήποτε πόλη, ποια θα διαλέγατε;"},{"c":"travel","t":"Ποιο ταξίδι θα θέλατε να επαναλάβετε;"},{"c":"travel","t":"Τι είναι πιο ενδιαφέρον: τα μουσεία ή οι βόλτες στους δρόμους;"},{"c":"food","t":"Ποιο φαγητό μαγειρεύετε καλύτερα;"},{"c":"food","t":"Γλυκό ή αλμυρό πρωινό;"},{"c":"food","t":"Ποιο φαγητό θα μπορούσατε να τρώτε κάθε μέρα;"},{"c":"food","t":"Ποιο φρούτο σας αρέσει περισσότερο;"},{"c":"food","t":"Ποιο φαγητό δεν έχετε δοκιμάσει ποτέ αλλά θα θέλατε;"},{"c":"food","t":"Τσάι ή καφές — και με τι;"},{"c":"food","t":"Ποια είναι η πιο ασυνήθιστη γεύση παγωτού που έχετε δοκιμάσει;"},{"c":"food","t":"Τι θα μαγειρεύατε για έναν επισκέπτη από άλλη χώρα;"},{"c":"food","t":"Πίτσα, σούπα ή σαλάτα: τι θα διαλέγατε για μεσημεριανό;"},{"c":"food","t":"Ποια συνταγή περνάει από γενιά σε γενιά στην οικογένειά σας;"},{"c":"food","t":"Ποιο φαγητό σας θυμίζει το σπίτι;"},{"c":"food","t":"Τι σας αρέσει να προσθέτετε σχεδόν σε όλα;"},{"c":"food","t":"Τι θα θέλατε να ψήσετε μαζί;"},{"c":"food","t":"Πικάντικο φαγητό: ναι ή όχι;"},{"c":"food","t":"Ποιο είναι το καλύτερο σνακ για ταξίδι;"},{"c":"food","t":"Ποιο φαγητό σας βγήκε κάποτε εντελώς στραβό;"},{"c":"food","t":"Ποια κουζίνα του κόσμου σας αρέσει περισσότερο;"},{"c":"food","t":"Τι είναι πιο νόστιμο: το σπιτικό φαγητό ή το φαγητό στο καφέ;"},{"c":"food","t":"Τι πίνετε όταν κάνει κρύο;"},{"c":"food","t":"Ποιο είναι το ιδανικό σας πρωινό;"},{"c":"food","t":"Ποιο φαγητό δεν σας άρεσε ως παιδιά αλλά σας αρέσει τώρα;"},{"c":"food","t":"Αν ανοίγατε ένα καφέ, τι θα είχε το μενού;"},{"c":"food","t":"Ποια είναι η πιο νόστιμη σούπα στον κόσμο;"},{"c":"food","t":"Πόσα κουταλάκια ζάχαρη βάζετε στο τσάι σας;"},{"c":"food","t":"Ποιο φαγητό θα θέλατε να μάθετε να μαγειρεύετε;"},{"c":"food","t":"Σοκολάτα: μαύρη, γάλακτος ή λευκή;"},{"c":"dreams","t":"Ποια δεξιότητα θα θέλατε να μάθετε φέτος;"},{"c":"dreams","t":"Πού θα θέλατε να ζείτε σε δέκα χρόνια;"},{"c":"dreams","t":"Ποιο είναι το μεγαλύτερο σχέδιό σας για το καλοκαίρι;"},{"c":"dreams","t":"Το σπίτι των ονείρων σας: δίπλα στη θάλασσα, στο δάσος ή στην πόλη;"},{"c":"dreams","t":"Ποια γλώσσα ονειρεύεστε να μιλάτε άπταιστα;"},{"c":"dreams","t":"Τι θα θέλατε να διδάξετε σε άλλους ανθρώπους;"},{"c":"dreams","t":"Ποια καλή πράξη ονειρεύεστε να κάνετε;"},{"c":"dreams","t":"Τι θα θέλατε να φτιάξετε με τα ίδια σας τα χέρια;"},{"c":"dreams","t":"Ποιο άθλημα θα θέλατε να δοκιμάσετε;"},{"c":"dreams","t":"Ποιο μέρος του χάρτη ονειρεύεστε να δείτε;"},{"c":"dreams","t":"Αν είχατε μια ολόκληρη χρονιά ελεύθερη, πώς θα τη γεμίζατε;"},{"c":"dreams","t":"Ποιο φυτό ή ποιον κήπο θα θέλατε να καλλιεργήσετε;"},{"c":"dreams","t":"Ποιο βιβλίο ονειρεύεστε να διαβάσετε ή να γράψετε;"},{"c":"dreams","t":"Ποια ικανότητα από τα παιδικά σας χρόνια θα θέλατε να ξαναποκτήσετε;"},{"c":"dreams","t":"Ποιο ρεκόρ θα θέλατε να σημειώσετε;"},{"c":"dreams","t":"Τι θέλετε να κάνετε πριν τελειώσει η χρονιά;"},{"c":"dreams","t":"Πώς θα ήταν η ιδανική σας μέρα ξεκούρασης;"},{"c":"dreams","t":"Ποιο επάγγελμα θα δοκιμάζατε για μία μόνο μέρα;"},{"c":"dreams","t":"Ποιο ζώο θα θέλατε να δείτε κάποτε από κοντά;"},{"c":"dreams","t":"Ποιο μικρό βήμα προς ένα όνειρο θα μπορούσατε να κάνετε αυτή την εβδομάδα;"},{"c":"dreams","t":"Ποιο ταξίδι θα σχεδιάζατε μαζί;"},{"c":"dreams","t":"Τι θα θέλατε να μάθετε ο ένας από τον άλλον;"},{"c":"dreams","t":"Ποιο σχέδιο θέλετε εδώ και καιρό να ξεκινήσετε;"},{"c":"dreams","t":"Πού θα θέλατε να περάσετε μια ολόκληρη ήσυχη μέρα;"},{"c":"dreams","t":"Ποια συγκέντρωση θα οργανώνατε για όλους τους φίλους σας;"},{"c":"dreams","t":"Τι θα εφευρίσκατε για να γίνει η ζωή πιο εύκολη;"},{"c":"whatif","t":"Αν μπορούσατε να πετάξετε, πού θα πηγαίνατε πρώτα;"},{"c":"whatif","t":"Αν τα ζώα μιλούσαν, με ποιο θα κουβεντιάζατε;"},{"c":"whatif","t":"Αν μπορούσατε να εξαφανιστείτε από τα μάτια όλων για μια μέρα, τι θα κάνατε;"},{"c":"whatif","t":"Αν μπορούσατε να διαλέξετε οποιοδήποτε ταλέντο, ποιο θα ήταν;"},{"c":"whatif","t":"Αν ζούσατε μέσα σε ένα βιβλίο, ποιο θα ήταν;"},{"c":"whatif","t":"Αν είχατε ένα ρομπότ βοηθό, τι θα έκανε;"},{"c":"whatif","t":"Αν μιλούσατε όλες τις γλώσσες, με ποιον θα συζητούσατε;"},{"c":"whatif","t":"Αν μπορούσατε να μεταφερθείτε σε οποιαδήποτε εποχή του χρόνου τώρα αμέσως, ποια θα ήταν;"},{"c":"whatif","t":"Αν είχατε δικό σας νησί, τι θα είχε πάνω;"},{"c":"whatif","t":"Αν μικραίνατε στο μέγεθος ενός μυρμηγκιού, τι θα εξερευνούσατε;"},{"c":"whatif","t":"Αν μπορούσατε να εφεύρετε μια νέα ξεχωριστή μέρα του χρόνου, πώς θα ήταν;"},{"c":"whatif","t":"Αν μπορούσατε να γυρίσετε πίσω τη μέρα σας, ποια στιγμή θα ξαναζούσατε;"},{"c":"whatif","t":"Αν ήσασταν καιρός, τι καιρός θα ήσασταν;"},{"c":"whatif","t":"Αν μπορούσατε να ζήσετε κάτω από το νερό, τι θα χτίζατε εκεί;"},{"c":"whatif","t":"Αν μπορούσατε να αλλάξετε δουλειά με κάποιον για μια μέρα, με ποιον θα ήταν;"},{"c":"whatif","t":"Αν είχατε δικό σας μουσείο, τι θα είχε μέσα;"},{"c":"whatif","t":"Αν μπορούσατε να μιλήσετε στα φυτά, τι θα τα ρωτούσατε;"},{"c":"whatif","t":"Αν όλα τα αυτοκίνητα εξαφανίζονταν για μια μέρα, πού θα περπατούσατε;"},{"c":"whatif","t":"Αν ήσασταν γεύση παγωτού, ποια θα ήσασταν;"},{"c":"whatif","t":"Αν μπορούσατε να ζήσετε μια μέρα σε μια άλλη χώρα, ποια θα ήταν;"},{"c":"whatif","t":"Αν το σπίτι σας είχε ρόδες, πού θα το οδηγούσατε;"},{"c":"whatif","t":"Αν ανοίγατε το δικό σας μαγαζί, τι θα πουλούσε;"},{"c":"whatif","t":"Αν χιόνιζε κάθε μέρα, τι θα άλλαζε;"},{"c":"whatif","t":"Αν είχατε μια μηχανή του χρόνου για μία ώρα, πού θα πηγαίνατε;"},{"c":"whatif","t":"Αν μπορούσατε να μάθετε σε ένα κατοικίδιο ένα κόλπο, ποιο θα ήταν;"},{"c":"whatif","t":"Αν γράφατε ένα βιβλίο, πώς θα λεγόταν;"},{"c":"funny","t":"Ποιο είναι το πιο αστείο λάθος του αυτόματου διορθωτή που σας έχει τύχει;"},{"c":"funny","t":"Ποια λέξη προφέρατε λάθος για πολύ καιρό;"},{"c":"funny","t":"Ποιο είναι το πιο παράξενο όνειρο που έχετε δει;"},{"c":"funny","t":"Τι σας κάνει πάντα να γελάτε, ακόμα κι όταν δεν πρέπει;"},{"c":"funny","t":"Ποιο είναι το πιο ανόητο πράγμα που έχετε αγοράσει ποτέ;"},{"c":"funny","t":"Ποιο ζώο σας φαίνεται το πιο αστείο;"},{"c":"funny","t":"Πείτε για μια φορά που τίποτα δεν πήγε όπως το σχεδιάζατε, αλλά τελικά ήταν διασκεδαστικό."},{"c":"funny","t":"Ποιο ανέκδοτο ξέρετε απέξω;"},{"c":"funny","t":"Πώς θα λεγόταν ένα κινούμενο σχέδιο για τη ζωή σας;"},{"c":"funny","t":"Ποια αστεία συνήθεια έχετε προσέξει στον εαυτό σας;"},{"c":"funny","t":"Ποιο είναι το πιο αστείο παρατσούκλι που σας έχουν δώσει;"},{"c":"funny","t":"Αν μια γάτα ή ένας σκύλος είχε μπλογκ, τι θα έγραφε εκεί;"},{"c":"funny","t":"Ποια ταινία σας έκανε να γελάσετε μέχρι δακρύων;"},{"c":"funny","t":"Τι αστείο σας έχει συμβεί στα μέσα μαζικής μεταφοράς;"},{"c":"funny","t":"Ποιος είναι ο πιο παράξενος συνδυασμός φαγητών που σας αρέσει;"},{"c":"funny","t":"Ποιος ήχος περιγράφει καλύτερα τα πρωινά σας;"},{"c":"funny","t":"Τι έχετε ψάξει ενώ το κρατούσατε στο χέρι σας;"},{"c":"funny","t":"Ποια αστεία ιστορία με τον καιρό έχετε να πείτε;"},{"c":"funny","t":"Αν τα λαχανικά είχαν χαρακτήρα, ποιο θα ήταν το πιο γκρινιάρικο;"},{"c":"funny","t":"Ποια είναι η πιο αστεία λέξη που ξέρετε σε άλλη γλώσσα;"},{"c":"funny","t":"Τι έχετε κάνει νομίζοντας ότι δεν σας έβλεπε κανείς;"},{"c":"funny","t":"Ποια αστεία φράση λέγεται συχνά στο σπίτι σας;"},{"c":"funny","t":"Πώς θα σας περιέγραφε το πιάτο σας μετά το μεσημεριανό;"},{"c":"funny","t":"Ποια είναι η πιο άτυχη φωτογραφία σας;"},{"c":"funny","t":"Ποια εντελώς άχρηστη υπερδύναμη θα διαλέγατε;"},{"c":"funny","t":"Αν το πρωινό σας είχε τίτλο σαν εφημερίδα, ποιος θα ήταν;"}];
